import * as AasStringification from "../src/stringification";
import * as AasTypes from "../src/types";

test("RecorD stringification round-trip Ok", () => {
  const literal = AasTypes.RecorD.Ok;

  const text = AasStringification.mustRecordToString(literal);
  expect(text).toStrictEqual("ok");

  const nullableText = AasStringification.recordToString(literal);
  expect(nullableText).toStrictEqual("ok");

  const parsed = AasStringification.recordFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("RecorD stringification round-trip NotOk", () => {
  const literal = AasTypes.RecorD.NotOk;

  const text = AasStringification.mustRecordToString(literal);
  expect(text).toStrictEqual("not-ok");

  const nullableText = AasStringification.recordToString(literal);
  expect(nullableText).toStrictEqual("not-ok");

  const parsed = AasStringification.recordFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("RecorD from invalid string", () => {
  const parsed = AasStringification.recordFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("RecorD invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <AasTypes.RecorD>9007199254740991;

  expect(AasStringification.recordToString(invalidLiteral)).toBeNull();
  expect(() => AasStringification.mustRecordToString(invalidLiteral)).toThrow();
});

